using System; using System.Linq; using System.Collections.Generic; using System.Data; using QuanLyNhanSu.Data; using QuanLyNhanSu.Models;
namespace QuanLyNhanSu.Services {
 public sealed class NhanSuService {
  readonly Db db; public NhanSuService():this(new Db()){} public NhanSuService(Db value){db=value;}
  static void Need(bool ok,string msg){if(!ok)throw new InvalidOperationException(msg);}
  static void Text(string v,string title){Need(!string.IsNullOrWhiteSpace(v),title+" không được trống.");}
  static string State(Session s,string nv){var o=s.Scalar("SELECT TrangThai FROM NhanVien WITH(UPDLOCK,HOLDLOCK) WHERE MaNV=@n",Db.P("@n",nv));Need(o!=null,"Không tìm thấy nhân viên.");return Convert.ToString(o);}
  static void Role(Session s,string nv,string pb){Need(Convert.ToInt32(s.Scalar("SELECT COUNT(*) FROM NhanVien WHERE MaNV=@n AND MaPB=@p AND TrangThai='CHINHTHUC'",Db.P("@n",nv),Db.P("@p",pb)))==1,"Người thực hiện không thuộc bộ phận được phép.");}
  static void OpenMonth(Session s,DateTime date){Need(Convert.ToInt32(s.Scalar("SELECT COUNT(*) FROM BangLuong WITH(UPDLOCK,HOLDLOCK) WHERE Nam=@y AND Thang=@m",Db.P("@y",date.Year),Db.P("@m",date.Month)))==0,"Tháng đã tính lương; không thay đổi dữ liệu nguồn.");}
  public DataTable Xem(string name){string[] allowed={"PhongBan","ChucVu","CaLamViec","NhanVien","QuyetDinh","HopDong","BaoHiem","KeHoachTuan","ChiTietKeHoach","BangChamCong","PhieuPhuTroi","ChiTietPhuTroi","PhieuChi","PhieuThu","BangLuong"};Need(allowed.Contains(name),"Bảng không hợp lệ.");return db.Query("SELECT * FROM dbo.["+name+"]");}
  public void DanhMuc(string loai,string ma,string ten,decimal so){Text(ma,"Mã");Text(ten,"Tên");db.Tx(s=>{if(loai=="PhongBan")s.Exec("INSERT PhongBan VALUES(@m,@t)",Db.P("@m",ma),Db.P("@t",ten));else if(loai=="ChucVu"){Need(so>=0,"Phụ cấp phải không âm.");s.Exec("INSERT ChucVu VALUES(@m,@t,@s)",Db.P("@m",ma),Db.P("@t",ten),Db.P("@s",so));}else{Need(loai=="CaLamViec"&&so>0&&so<=24,"Ca cần số giờ từ 0 đến 24.");s.Exec("INSERT CaLamViec VALUES(@m,@t,@s)",Db.P("@m",ma),Db.P("@t",ten),Db.P("@s",so));}return 0;});}
  public void TuyenDung(string nv,string ten,DateTime sinh,string pb,string qd,DateTime tu,DateTime den,decimal luong,string noidung,string nguoilap){Text(nv,"Mã NV");Text(ten,"Họ tên");Text(qd,"Số QĐ");Text(noidung,"Điều khoản");Need(sinh.Date<DateTime.Today&&tu<=den&&luong>0,"Ngày sinh, thời gian thử việc hoặc lương không hợp lệ.");db.Tx(s=>{Role(s,nguoilap,"PB01");OpenMonth(s,tu);s.Exec("INSERT NhanVien(MaNV,HoTen,NgaySinh,MaPB,TrangThai) VALUES(@n,@t,@s,@p,'THUVIEC')",Db.P("@n",nv),Db.P("@t",ten),Db.P("@s",sinh),Db.P("@p",pb));s.Exec("INSERT QuyetDinh(SoQD,Loai,NgayQD,HieuLuc,DenNgay,MaNV,SoTien,NoiDung) VALUES(@q,'TUYENDUNG',@d,@d,@e,@n,@l,@t)",Db.P("@q",qd),Db.P("@d",tu),Db.P("@e",den),Db.P("@n",nv),Db.P("@l",luong),Db.P("@t",noidung));return 0;});}
  public void KetQua(string nv,bool dat,DateTime ngay,string ns){db.Tx(s=>{Role(s,ns,"PB01");Need(State(s,nv)=="THUVIEC","Chỉ ghi kết quả cho nhân viên thử việc.");Need(Convert.ToInt32(s.Scalar("SELECT COUNT(*) FROM QuyetDinh WHERE MaNV=@n AND Loai='TUYENDUNG' AND DenNgay<=@d AND NgayKy IS NOT NULL",Db.P("@n",nv),Db.P("@d",ngay)))==1,"Chưa hết thử việc hoặc QĐ tuyển dụng chưa ký.");OpenMonth(s,ngay);s.Exec("UPDATE NhanVien SET TrangThai=@t,NgayKetQua=@d WHERE MaNV=@n",Db.P("@n",nv),Db.P("@t",dat?"DAT":"NGHIVIEC"),Db.P("@d",ngay));return 0;});}
  public void HopDong(string hd,string nv,string loai,DateTime tu,DateTime? den,decimal yt,decimal xh,string ns){Text(hd,"Số HĐ");Need(loai=="DAIHAN"||loai=="NGANHAN","Loại hợp đồng không hợp lệ.");Need(!den.HasValue||den>=tu,"Ngày kết thúc sai.");Need(loai=="DAIHAN"||den.HasValue,"HĐ ngắn hạn cần ngày kết thúc.");Need(yt>=0&&xh>=0,"Mức đóng không âm.");db.Tx(s=>{Role(s,ns,"PB01");string state=State(s,nv);Need(state=="DAT"||state=="CHINHTHUC","Cần kết quả thử việc đạt.");Need(Convert.ToInt32(s.Scalar("SELECT COUNT(*) FROM QuyetDinh WHERE MaNV=@n AND Loai='TUYENDUNG' AND DenNgay>=@d",Db.P("@n",nv),Db.P("@d",tu)))==0,"Hợp đồng chính thức phải sau thời gian thử việc.");Need(Convert.ToInt32(s.Scalar("SELECT COUNT(*) FROM NhanVien WHERE MaNV=@n AND NgayKetQua>@d",Db.P("@n",nv),Db.P("@d",tu)))==0,"Ngày hợp đồng trước ngày đánh giá đạt.");OpenMonth(s,tu);Need(Convert.ToInt32(s.Scalar("SELECT COUNT(*) FROM HopDong WITH(UPDLOCK,HOLDLOCK) WHERE MaNV=@n AND TuNgay<=ISNULL(@e,'99991231') AND ISNULL(DenNgay,'99991231')>=@d",Db.P("@n",nv),Db.P("@d",tu),Db.P("@e",den)))==0,"Thời gian hợp đồng chồng nhau.");s.Exec("INSERT HopDong VALUES(@h,@n,@l,@d,@e)",Db.P("@h",hd),Db.P("@n",nv),Db.P("@l",loai),Db.P("@d",tu),Db.P("@e",den));if(loai=="DAIHAN"){s.Exec("INSERT BaoHiem VALUES(@a,@h,'BHYT',@v),(@b,@h,'BHXH',@w)",Db.P("@a",hd+"-YT"),Db.P("@b",hd+"-XH"),Db.P("@h",hd),Db.P("@v",yt),Db.P("@w",xh));}s.Exec("UPDATE NhanVien SET TrangThai='CHINHTHUC' WHERE MaNV=@n",Db.P("@n",nv));return 0;});}
  public void LapQD(string q,string loai,DateTime ngay,DateTime hl,string nv,string pb,string cv,decimal tien,decimal pc,decimal dh,string nd,string cach,string ns){Text(q,"Số QĐ");Text(nd,"Nội dung");Need(new[]{"LUONG","CHUCVU","KHENTHUONG","KYLUAT"}.Contains(loai),"Loại QĐ không hợp lệ.");Need(hl>=ngay&&tien>=0&&pc>=0&&dh>=0,"Ngày hiệu lực hoặc số tiền không hợp lệ.");Need(string.IsNullOrWhiteSpace(nv)!=string.IsNullOrWhiteSpace(pb),"Chọn đúng một cá nhân hoặc tập thể.");Need(string.IsNullOrWhiteSpace(pb)||(loai=="KHENTHUONG"||loai=="KYLUAT"),"QĐ lương/chức vụ phải cho cá nhân.");Need(cach=="PHIEU"||(cach=="TRULUONG"&&loai=="KYLUAT"&&!string.IsNullOrWhiteSpace(nv)),"Chỉ phạt cá nhân được chọn trừ lương.");Need(loai!="CHUCVU"||!string.IsNullOrWhiteSpace(cv),"Chọn chức vụ.");db.Tx(s=>{Role(s,ns,"PB01");if(!string.IsNullOrWhiteSpace(nv))Need(State(s,nv)!="NGHIVIEC","Nhân viên đã nghỉ việc.");OpenMonth(s,hl);s.Exec("INSERT QuyetDinh(SoQD,Loai,NgayQD,HieuLuc,MaNV,MaPB,MaCV,SoTien,PhuCapLuong,PhuCapDocHai,NoiDung,CachXuLy) VALUES(@q,@l,@d,@h,@n,@p,@c,@v,@pc,@dh,@t,@x)",Db.P("@q",q),Db.P("@l",loai),Db.P("@d",ngay),Db.P("@h",hl),Db.P("@n",string.IsNullOrWhiteSpace(nv)?null:nv),Db.P("@p",string.IsNullOrWhiteSpace(pb)?null:pb),Db.P("@c",loai=="CHUCVU"?cv:null),Db.P("@v",tien),Db.P("@pc",pc),Db.P("@dh",dh),Db.P("@t",nd),Db.P("@x",cach));return 0;});}
  public void KyQD(string q,string gd,DateTime ngay){db.Tx(s=>{Role(s,gd,"PB05");var t=s.Query("SELECT * FROM QuyetDinh WITH(UPDLOCK,HOLDLOCK) WHERE SoQD=@q",Db.P("@q",q));Need(t.Rows.Count==1,"Không có QĐ.");var r=t.Rows[0];Need(r["NgayKy"]==DBNull.Value,"QĐ đã ký.");Need(ngay>=Convert.ToDateTime(r["NgayQD"]),"Ngày ký trước ngày QĐ.");OpenMonth(s,ngay);OpenMonth(s,Convert.ToDateTime(r["HieuLuc"]));string loai=Convert.ToString(r["Loai"]);if(loai=="LUONG"||loai=="CHUCVU")Need(Convert.ToInt32(s.Scalar("SELECT COUNT(*) FROM QuyetDinh WHERE MaNV=@n AND Loai=@l AND HieuLuc=@h AND NgayKy IS NOT NULL",Db.P("@n",r["MaNV"]),Db.P("@l",loai),Db.P("@h",r["HieuLuc"])))==0,"Đã có QĐ cùng loại và ngày hiệu lực.");s.Exec("UPDATE QuyetDinh SET NguoiKy=@g,NgayKy=@d WHERE SoQD=@q",Db.P("@g",gd),Db.P("@d",ngay),Db.P("@q",q));return 0;});}
  public void LapPhieu(string so,string q,DateTime ngay,string kt){Text(so,"Số phiếu");db.Tx(s=>{Role(s,kt,"PB02");var t=s.Query("SELECT * FROM QuyetDinh WITH(UPDLOCK,HOLDLOCK) WHERE SoQD=@q",Db.P("@q",q));Need(t.Rows.Count==1,"Không có quyết định.");var r=t.Rows[0];Need(r["NgayKy"]!=DBNull.Value&&ngay>=Convert.ToDateTime(r["NgayKy"]),"QĐ chưa ký hoặc ngày phiếu trước ngày ký.");string loai=Convert.ToString(r["Loai"]);Need((loai=="KHENTHUONG"||loai=="KYLUAT")&&Convert.ToString(r["CachXuLy"])=="PHIEU","Không lập phiếu cho QĐ này.");Need(Convert.ToDecimal(r["SoTien"])>0,"Số tiền phải dương.");string table=loai=="KHENTHUONG"?"PhieuChi":"PhieuThu";s.Exec("INSERT "+table+" VALUES(@s,@q,@d,@v,@n)",Db.P("@s",so),Db.P("@q",q),Db.P("@d",ngay),Db.P("@v",r["SoTien"]),Db.P("@n",kt));return 0;});}
  public void KeHoach(string ma,string pb,DateTime thuHai,DateTime lap,string truong,List<DongKeHoach> ds){Text(ma,"Mã kế hoạch");Need(thuHai.DayOfWeek==DayOfWeek.Monday&&lap<thuHai,"Tuần bắt đầu thứ Hai; lập trước tuần.");Need(ds!=null&&ds.Count>0,"Kế hoạch cần chi tiết.");db.Tx(s=>{Need(Convert.ToInt32(s.Scalar("SELECT COUNT(*) FROM NhanVien n JOIN QuyetDinh q ON q.MaNV=n.MaNV WHERE n.MaNV=@n AND n.MaPB=@p AND q.Loai='CHUCVU' AND q.NgayKy<=@d AND q.HieuLuc<=@d AND q.MaCV IN ('CV01','CV02') AND NOT EXISTS(SELECT 1 FROM QuyetDinh x WHERE x.MaNV=q.MaNV AND x.Loai='CHUCVU' AND x.NgayKy<=@d AND x.HieuLuc<=@d AND x.HieuLuc>q.HieuLuc)",Db.P("@n",truong),Db.P("@p",pb),Db.P("@d",lap)))==1,"Người lập phải là trưởng đơn vị có QĐ hiệu lực.");s.Exec("INSERT KeHoachTuan VALUES(@m,@p,@d,@l,@n)",Db.P("@m",ma),Db.P("@p",pb),Db.P("@d",thuHai),Db.P("@l",lap),Db.P("@n",truong));foreach(var x in ds){OpenMonth(s,x.Ngay);Need(x.Ngay>=thuHai&&x.Ngay<thuHai.AddDays(7)&&x.GioPhuTroi>=0&&x.GioPhuTroi<=24,"Dòng phân công sai tuần hoặc số giờ.");Need(Convert.ToInt32(s.Scalar("SELECT COUNT(*) FROM NhanVien WHERE MaNV=@n AND MaPB=@p AND TrangThai<>'NGHIVIEC'",Db.P("@n",x.MaNV),Db.P("@p",pb)))==1,"Nhân viên phải thuộc đơn vị.");s.Exec("INSERT ChiTietKeHoach VALUES(@m,@n,@d,@c,@g)",Db.P("@m",ma),Db.P("@n",x.MaNV),Db.P("@d",x.Ngay),Db.P("@c",x.MaCa),Db.P("@g",x.GioPhuTroi));}foreach(var g in ds.GroupBy(x=>new{x.MaNV,x.Ngay})){decimal total=Convert.ToDecimal(s.Scalar("SELECT ISNULL(SUM(c.SoGio+d.GioPhuTroi),0) FROM ChiTietKeHoach d JOIN CaLamViec c ON c.MaCa=d.MaCa WHERE d.MaNV=@n AND d.Ngay=@d",Db.P("@n",g.Key.MaNV),Db.P("@d",g.Key.Ngay)));Need(total<=24,"Tổng ca và phụ trội trong ngày vượt 24 giờ.");}return 0;});}
  public void ChamCong(string nv,DateTime ngay,decimal gio,string bcc){Need(gio>=0&&gio<=24,"Giờ công từ 0 đến 24.");db.Tx(s=>{Role(s,bcc,"PB04");Need(State(s,nv)!="NGHIVIEC","Nhân viên đã nghỉ.");OpenMonth(s,ngay);Need(Convert.ToDecimal(s.Scalar("SELECT ISNULL(SUM(c.SoGio),0) FROM ChiTietKeHoach d JOIN CaLamViec c ON d.MaCa=c.MaCa WHERE d.MaNV=@n AND d.Ngay=@d",Db.P("@n",nv),Db.P("@d",ngay)))>=gio,"Giờ công vượt kế hoạch hoặc chưa phân ca.");s.Exec("IF EXISTS(SELECT 1 FROM BangChamCong WHERE MaNV=@n AND Ngay=@d) UPDATE BangChamCong SET SoGio=@g,NguoiCham=@b WHERE MaNV=@n AND Ngay=@d ELSE INSERT BangChamCong VALUES(@n,@d,@g,@b)",Db.P("@n",nv),Db.P("@d",ngay),Db.P("@g",gio),Db.P("@b",bcc));return 0;});}
  public void PhuTroi(string so,DateTime ngay,string hinh,decimal gio,string bcc,List<DongPhuTroi> ds){Text(so,"Số phiếu");Need(gio>0&&gio<=24&&ds!=null&&ds.Count>0,"Phiếu cần giờ hợp lệ và danh sách.");db.Tx(s=>{Role(s,bcc,"PB04");OpenMonth(s,ngay);s.Exec("INSERT PhieuPhuTroi VALUES(@s,@d,@h,@g,@n)",Db.P("@s",so),Db.P("@d",ngay),Db.P("@h",hinh),Db.P("@g",gio),Db.P("@n",bcc));foreach(var x in ds){Need(State(s,x.MaNV)!="NGHIVIEC"&&x.SoGio>0&&x.SoGio<=gio,"Giờ tham gia vượt phiếu hoặc nhân viên đã nghỉ.");decimal plan=Convert.ToDecimal(s.Scalar("SELECT ISNULL(SUM(GioPhuTroi),0) FROM ChiTietKeHoach WHERE MaNV=@n AND Ngay=@d",Db.P("@n",x.MaNV),Db.P("@d",ngay)));decimal old=Convert.ToDecimal(s.Scalar("SELECT ISNULL(SUM(c.SoGio),0) FROM ChiTietPhuTroi c JOIN PhieuPhuTroi p ON p.SoPhieu=c.SoPhieu WHERE c.MaNV=@n AND p.Ngay=@d",Db.P("@n",x.MaNV),Db.P("@d",ngay)));Need(old+x.SoGio<=plan,"Tổng giờ phụ trội vượt kế hoạch.");decimal normal=Convert.ToDecimal(s.Scalar("SELECT ISNULL(SUM(SoGio),0) FROM BangChamCong WHERE MaNV=@n AND Ngay=@d",Db.P("@n",x.MaNV),Db.P("@d",ngay)));Need(normal+old+x.SoGio<=24,"Tổng giờ công và phụ trội vượt 24 giờ.");s.Exec("INSERT ChiTietPhuTroi VALUES(@s,@n,@g)",Db.P("@s",so),Db.P("@n",x.MaNV),Db.P("@g",x.SoGio));}return 0;});}
  public DataTable TinhLuong(int nam,int thang,decimal gioChuan,string kt){Need(nam>=2000&&nam<=2100&&thang>=1&&thang<=12&&gioChuan>0,"Kỳ lương hoặc giờ chuẩn sai.");return db.Tx(s=>{Role(s,kt,"PB02");var tu=new DateTime(nam,thang,1);var den=tu.AddMonths(1);OpenMonth(s,tu);Need(Convert.ToInt32(s.Scalar("SELECT COUNT(*) FROM QuyetDinh WHERE Loai IN ('LUONG','CHUCVU') AND NgayKy IS NOT NULL AND ((HieuLuc>@d AND HieuLuc<@e) OR (NgayKy>@d AND NgayKy<@e))",Db.P("@d",tu),Db.P("@e",den)))==0,"Có thay đổi lương/chức vụ giữa tháng; cần tách kỳ trước khi tính.");Need(Convert.ToInt32(s.Scalar("SELECT COUNT(*) FROM HopDong WHERE TuNgay>@d AND TuNgay<@e OR DenNgay>=@d AND DenNgay<DATEADD(day,-1,@e)",Db.P("@d",tu),Db.P("@e",den)))==0,"Có thay đổi hợp đồng giữa tháng; cần tách kỳ.");var ds=s.Query("SELECT MaNV FROM HopDong WHERE TuNgay<=@d AND (DenNgay IS NULL OR DenNgay>=DATEADD(day,-1,@e)) UNION SELECT MaNV FROM QuyetDinh WHERE Loai='TUYENDUNG' AND HieuLuc<=@d AND NgayKy<=@d AND DenNgay>=DATEADD(day,-1,@e)",Db.P("@d",tu),Db.P("@e",den));Need(ds.Rows.Count>0,"Không có nhân viên có hợp đồng hoặc quyết định thử việc trọn kỳ.");foreach(DataRow r in ds.Rows){string nv=Convert.ToString(r[0]);var l=s.Query("SELECT TOP 1 * FROM QuyetDinh WHERE MaNV=@n AND HieuLuc<=@d AND NgayKy<=@d AND (Loai='LUONG' AND EXISTS(SELECT 1 FROM HopDong WHERE MaNV=@n AND TuNgay<=@d AND (DenNgay IS NULL OR DenNgay>=@d)) OR Loai='TUYENDUNG' AND DenNgay>=DATEADD(day,-1,DATEADD(month,1,@d))) ORDER BY CASE WHEN Loai='LUONG' THEN 0 ELSE 1 END,HieuLuc DESC",Db.P("@n",nv),Db.P("@d",tu));Need(l.Rows.Count==1,"Thiếu QĐ lương đã ký cho "+nv);var lr=l.Rows[0];decimal basic=Convert.ToDecimal(lr["SoTien"]);decimal cv=Convert.ToDecimal(s.Scalar("SELECT ISNULL((SELECT TOP 1 SoTien FROM QuyetDinh WHERE MaNV=@n AND Loai='CHUCVU' AND HieuLuc<=@d AND NgayKy<=@d ORDER BY HieuLuc DESC),0)",Db.P("@n",nv),Db.P("@d",tu)));decimal pc=Convert.ToDecimal(lr["PhuCapLuong"])+Convert.ToDecimal(lr["PhuCapDocHai"])+cv;decimal cong=Convert.ToDecimal(s.Scalar("SELECT ISNULL(SUM(SoGio),0) FROM BangChamCong WHERE MaNV=@n AND Ngay>=@d AND Ngay<@e",Db.P("@n",nv),Db.P("@d",tu),Db.P("@e",den)));Need(cong<=gioChuan,"Giờ công vượt giờ chuẩn cho "+nv);decimal pt=Convert.ToDecimal(s.Scalar("SELECT ISNULL(SUM(c.SoGio),0) FROM ChiTietPhuTroi c JOIN PhieuPhuTroi p ON c.SoPhieu=p.SoPhieu WHERE c.MaNV=@n AND p.Ngay>=@d AND p.Ngay<@e",Db.P("@n",nv),Db.P("@d",tu),Db.P("@e",den)));decimal bh=Convert.ToDecimal(s.Scalar("SELECT ISNULL(SUM(b.MucDong),0) FROM BaoHiem b JOIN HopDong h ON b.SoHD=h.SoHD WHERE h.MaNV=@n AND h.TuNgay<=@d AND (h.DenNgay IS NULL OR h.DenNgay>=DATEADD(day,-1,@e))",Db.P("@n",nv),Db.P("@d",tu),Db.P("@e",den)));decimal phat=Convert.ToDecimal(s.Scalar("SELECT ISNULL(SUM(SoTien),0) FROM QuyetDinh WHERE MaNV=@n AND Loai='KYLUAT' AND CachXuLy='TRULUONG' AND NgayKy>=@d AND NgayKy<@e",Db.P("@n",nv),Db.P("@d",tu),Db.P("@e",den)));decimal tiencong=Math.Round(basic*cong/gioChuan,0,MidpointRounding.AwayFromZero),tienpt=Math.Round(basic/gioChuan*1.5m*pt,0,MidpointRounding.AwayFromZero);decimal net=tiencong+pc+tienpt-bh-phat;Need(net>=0,"Thực lĩnh âm cho "+nv+"; cần xử lý khấu trừ.");s.Exec("INSERT BangLuong VALUES(@n,@y,@m,@gc,@g,@pt,@l,@pc,@tc,@tp,@bh,@p,@v)",Db.P("@n",nv),Db.P("@y",nam),Db.P("@m",thang),Db.P("@gc",gioChuan),Db.P("@g",cong),Db.P("@pt",pt),Db.P("@l",basic),Db.P("@pc",pc),Db.P("@tc",tiencong),Db.P("@tp",tienpt),Db.P("@bh",bh),Db.P("@p",phat),Db.P("@v",net));}return s.Query("SELECT * FROM BangLuong WHERE Nam=@y AND Thang=@m",Db.P("@y",nam),Db.P("@m",thang));});}
  public DataTable ThongKe(int nam,int thang){return db.Query("SELECT n.MaPB,COUNT(*) SoNhanVien,SUM(b.TienCong) TienCong,SUM(b.TienPhuTroi) TienPhuTroi,SUM(b.BaoHiem) BaoHiem,SUM(b.TruPhat) TruPhat,SUM(b.ThucLinh) ThucLinh FROM BangLuong b JOIN NhanVien n ON b.MaNV=n.MaNV WHERE Nam=@y AND Thang=@m GROUP BY n.MaPB",Db.P("@y",nam),Db.P("@m",thang));}
 }
}
